) calc(var(--p) * 1%),var(--soft) 0);\n  -webkit-mask:radial-gradient(farthest-side,transparent calc(100% - 9px),currentColor calc(100% - 8px));\n  mask:radial-gradient(farthest-side,transparent calc(100% - 9px),currentColor calc(100% - 8px))}\n.ring-in{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px}\n.time{font-variant-numeric:tabular-nums;font-weight:700;letter-spacing:.02em;line-height:1.1}\n.ring-in .time{font-size:calc(var(--rs) * .2)}\n.sub{font-size:11px;color:var(--muted)}\n\n.bar-wrap{display:flex;flex-direction:column;gap:6px;flex:none}\n.bar-wrap .time{font-size:36px;text-align:center}\n.bar{--p:0;--c:var(--accent);height:6px;border-radius:3px;background:var(--soft);overflow:hidden}\n.bar[data-phase=\"break\"]{--c:var(--accent-alt)}\n.bar i{display:block;height:100%;width:calc(var(--p) * 1%);background:var(--c)}\n\n.tb{min-width:0;display:flex;flex-direction:column;gap:2px;flex:none}\n.tag{font-size:11px;color:var(--muted);letter-spacing:.04em}\n.tag::before{content:\"\";display:inline-block;width:7px;height:7px;border-radius:50%;margin-right:5px;background:var(--accent)}\n.tag[data-phase=\"break\"]::before{background:var(--accent-alt)}\n.task{font-weight:600;font-size:14px;overflow-wrap:anywhere;max-height:2.8em;overflow-y:auto;min-width:0}\n.card[data-size=\"3x3\"] .task{font-size:13px}\n\n.ctl{display:flex;gap:8px;flex:none}\n.ctl .btn{flex:1;min-width:0}\n\n.btn{min-height:34px;padding:0 12px;border:1px solid var(--line);border-radius:10px;background:var(--button-paper,var(--panel-paper));color:var(--ink);font-size:13px;cursor:pointer;white-space:nowrap}\n.btn.primary{background:var(--accent);color:var(--on-accent);border-color:transparent;font-weight:600}\n.btn.warn{border-color:var(--ink);font-weight:700}\n.btn.big{min-height:38px;width:100%}\n.btn:disabled{opacity:.45;cursor:not-allowed}\n\n.form{display:flex;flex-direction:column;gap:8px;min-width:0;flex:none}\n.inp{width:100%;min-height:36px;padding:0 10px;border:1px solid var(--line);border-radius:10px;background:var(--paper);color:var(--ink);font-size:14px;min-width:0}\n.inp::placeholder{color:var(--muted)}\n.chip{align-self:flex-start;max-width:100%;padding:3px 0;border:0;background:none;color:var(--muted);font-size:12px;text-align:left;cursor:pointer;text-decoration:underline;text-underline-offset:3px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n\n.dur{display:flex;flex-direction:column;gap:6px;min-width:0;flex:none}\n.dh{font-size:11px;color:var(--muted);letter-spacing:.04em}\n.step{display:flex;align-items:center;gap:6px;min-width:0}\n.lab{width:2.6em;flex:none;font-size:12px}\n.sbtn{width:30px;height:30px;flex:none;padding:0;border:1px solid var(--line);border-radius:8px;background:var(--button-paper,var(--panel-paper));color:var(--ink);font-size:16px;line-height:1;cursor:pointer}\n.num{flex:1;min-width:0;width:100%;height:30px;padding:0 4px;border:1px solid var(--line);border-radius:8px;background:var(--paper);color:var(--ink);font-size:14px;text-align:center;font-variant-numeric:tabular-nums;-moz-appearance:textfield;appearance:textfield}\n.num::-webkit-inner-spin-button,.num::-webkit-outer-spin-button{-webkit-appearance:none;margin:0}\n.hint{font-size:11px;color:var(--muted);line-height:1.4}\n\n.lst{flex:1;min-height:60px;min-width:0;display:flex;flex-direction:column;gap:4px}\n.rows{list-style:none;margin:0;padding:0;flex:1;min-height:0;overflow:auto}\n.row{display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:8px;align-items:start;padding:6px 0;border-bottom:1px solid var(--line)}\n.rt{min-width:0;overflow-wrap:anywhere}\n.no,.rm{font-size:12px;color:var(--muted);font-variant-numeric:tabular-nums;white-space:nowrap}\n.empty{font-size:12px;color:var(--muted);padding:6px 0}\n";
function pad2(n){return n<10?'0'+n:''+n}
function dstr(ts){var d=new Date(ts);return d.getFullYear()+'-'+pad2(d.getMonth()+1)+'-'+pad2(d.getDate())}
function hhmm(ts){var d=new Date(ts);return pad2(d.getHours())+':'+pad2(d.getMinutes())}
function mmss(ms){var t=Math.max(0,Math.ceil(ms/1000));return pad2(Math.floor(t/60))+':'+pad2(t%60)}
function toInt(v,lo,hi,fb){var n=Math.round(Number(v));if(!isFinite(n))return fb;return Math.min(hi,Math.max(lo,n))}

function norm(s){
  var b=s&&typeof s==='object'?s:{};
  var st=b.settings||{};
  return Object.assign({},b,{
    settings:{focusMin:toInt(st.focusMin,1,180,25),breakMin:toInt(st.breakMin,1,60,5)},
    rounds:Array.isArray(b.rounds)?b.rounds:[],
    session:b.session&&typeof b.session==='object'?b.session:null
  });
}

function initialize(s){
  var b=s&&typeof s==='object'?s:{};
  if(b.settings&&Array.isArray(b.rounds)&&('session' in b))return s;
  return norm(b);
}

// 把已经到点的阶段结算掉：专注结束记一轮并自动进入休息；休息结束回到空闲。
// 关闭卡片期间到点的阶段，也按原定结束时刻补记，所以重新打开能接着用。
function settle(s,now){
  var ses=s.session,rounds=s.rounds,changed=false;
  while(ses&&ses.status==='running'&&ses.endAt<=now){
    changed=true;
    if(ses.phase==='focus'){
      var sid=ses.id;
      if(!rounds.some(function(r){return r.id===sid})){
        rounds=rounds.concat([{id:ses.id,task:ses.task,day:dstr(ses.endAt),at:ses.endAt,minutes:Math.max(1,Math.round(ses.totalMs/60000))}]);
      }
      var bm=s.settings.breakMin*60000;
      ses={id:ses.id,task:ses.task,phase:'break',status:'running',totalMs:bm,endAt:ses.endAt+bm};
    }else{
      ses=null;
    }
  }
  return changed?Object.assign({},s,{session:ses,rounds:rounds}):s;
}


function mount(ctx){
  const {root,el,state,ui,update,commit,redraw,uid,day}=ctx;
  const size=ctx.size||root.dataset.size||'3x3';
  const roomy=size==='3x6'||size==='6x6';
  const S=norm(state);
  const ses=S.session;
  const today=day();
  const todayRounds=S.rounds.filter(r=>r.day===today);
  ui.draft=ui.draft||{task:''};
  const view=roomy?'main':(ui.view||'main');
  let timeEl=null,pEl=null,timer=null,t0=null;

  function act(fn){
    return update(s=>fn(settle(norm(s),Date.now())));
  }
  function setView(v){ui.view=v;ui.confirm=false;redraw()}

  function startRound(){
    const task=(ui.draft.task||'').trim().slice(0,80);
    if(!task||ses)return;
    const id=uid();
    commit(s=>{
      const n=settle(norm(s),Date.now());
      if(n.session)return n;
      const tm=n.settings.focusMin*60000;
      return Object.assign({},n,{session:{id:id,task:task,phase:'focus',status:'running',totalMs:tm,endAt:Date.now()+tm}});
    },Object.assign({},ui,{draft:{task:''},view:'main',confirm:false}));
  }
  function pause(){
    act(n=>{
      const x=n.session;
      if(!x||x.status!=='running')return n;
      return Object.assign({},n,{session:Object.assign({},x,{status:'paused',endAt:null,remainingMs:Math.max(0,x.endAt-Date.now())})});
    });
  }
  function resume(){
    act(n=>{
      const x=n.session;
      if(!x||x.status!=='paused')return n;
      const r=Object.assign({},x,{status:'running',endAt:Date.now()+(x.remainingMs||0)});
      delete r.remainingMs;
      return Object.assign({},n,{session:r});
    });
  }
  function endSession(){
    ui.confirm=false;
    act(n=>Object.assign({},n,{session:null}));
  }
  // 改时长：下一轮起沿用；进行中的同类阶段同步增减剩余时间
  function changeDur(kind,fn){
    act(n=>{
      const key=kind==='focus'?'focusMin':'breakMin';
      const old=n.settings[key];
      const raw=fn(old);
      if(raw===''||raw==null)return n;
      const val=toInt(raw,1,kind==='focus'?180:60,old);
      if(val===old)return n;
      const settings=Object.assign({},n.settings);
      settings[key]=val;
      let x=n.session;
      if(x&&x.phase===kind){
        const delta=(val-old)*60000;
        x=Object.assign({},x,{totalMs:Math.max(60000,x.totalMs+delta)});
        if(x.status==='running')x.endAt=x.endAt+delta;
        else x.remainingMs=Math.max(0,(x.remainingMs||0)+delta);
      }
      return Object.assign({},n,{settings:settings,session:x});
    });
  }

  function remaining(){
    if(!ses)return S.settings.focusMin*60000;
    return ses.status==='running'?ses.endAt-Date.now():(ses.remainingMs||0);
  }
  function paint(){
    const rem=remaining();
    if(timeEl)timeEl.textContent=mmss(rem);
    if(pEl){
      const p=ses?Math.min(100,Math.max(0,100*(1-rem/Math.max(1,ses.totalMs)))):0;
      pEl.style.setProperty('--p',p.toFixed(2));
    }
  }
  function settleNow(){
    if(ui.settling||Date.now()<(ui.retryAt||0))return;
    ui.settling=true;
    update(s=>settle(norm(s),Date.now())).then(
      ()=>{ui.settling=false},
      ()=>{ui.settling=false;ui.retryAt=Date.now()+5000}
    );
  }
  function tick(){
    if(day()!==today){redraw();return}
    if(ses&&ses.status==='running'&&ses.endAt<=Date.now())settleNow();
    paint();
  }


  function btn(label,fn,cls,disabled){
    return el('button',{type:'button',class:'btn '+(cls||''),onclick:fn,disabled:!!disabled},label);
  }
  function phaseOf(){return ses?ses.phase:'idle'}

  function head(){
    const n=todayRounds.length;
    const cnt=[el('b',{},String(n)),' 轮'];
    const right=[];
    if(roomy){
      right.push(el('span',{class:'badge'},'今日完成 ',...cnt));
    }else{
      right.push(el('button',{type:'button',class:'badge link','aria-label':'查看今日完成记录',onclick:()=>setView('rounds')},'今日 ',...cnt));
      right.push(el('button',{type:'button',class:'badge link','aria-label':'调整时长',onclick:()=>setView('settings')},'时长'));
    }
    return el('div',{class:'head'},el('span',{class:'ttl'},size==='3x3'?'专注':'专注计时器'),el('span',{class:'head-r'},...right));
  }
  function subHead(title){
    return el('div',{class:'head'},
      el('button',{type:'button',class:'badge link',onclick:()=>setView('main')},'‹ 返回'),
      el('span',{class:'ttl'},title));
  }

  function ring(){
    timeEl=el('div',{class:'time',role:'timer'},mmss(remaining()));
    const sub=ses?(ses.status==='paused'?'已暂停':(ses.phase==='focus'?'专注':'休息')):'专注时长';
    pEl=el('div',{class:'ring','data-phase':phaseOf()},
      el('div',{class:'ring-track'}),
      el('div',{class:'ring-in'},timeEl,el('div',{class:'sub'},sub)));
    return pEl;
  }
  function bar(){
    timeEl=el('div',{class:'time',role:'timer'},mmss(remaining()));
    pEl=el('div',{class:'bar','data-phase':phaseOf()},el('i'));
    return el('div',{class:'bar-wrap'},timeEl,pEl);
  }

  function taskBlock(){
    const focus=ses.phase==='focus';
    const st=ses.status==='paused'?' · 已暂停':'';
    return el('div',{class:'tb'},
      el('div',{class:'tag','data-phase':ses.phase},(focus?'专注中':'休息中')+st),
      el('div',{class:'task'},focus?ses.task:'已完成：'+ses.task));
  }
  function controls(){
    if(ui.confirm){
      return el('div',{class:'ctl'},
        btn('确认放弃',endSession,'warn'),
        btn('取消',()=>{ui.confirm=false;redraw()}));
    }
    const main=ses.status==='running'?btn('暂停',pause,'primary'):btn('继续',resume,'primary');
    const second=ses.phase==='focus'?btn('放弃本轮',()=>{ui.confirm=true;redraw()}):btn('跳过休息',endSession);
    return el('div',{class:'ctl'},main,second);
  }

  function form(){
    const go=el('button',{type:'button',class:'btn primary big',disabled:!ui.draft.task.trim(),onclick:startRound},'开始专注 '+S.settings.focusMin+' 分钟');
    const inp=el('input',{class:'inp',type:'text',maxlength:'80',value:ui.draft.task,placeholder:'这一轮要做什么？（必填）','aria-label':'这一轮要做什么',
      oninput:()=>{ui.draft.task=inp.value;go.disabled=!inp.value.trim()},
      onkeydown:e=>{if(e.key==='Enter'){e.preventDefault();ui.draft.task=inp.value;startRound()}}});
    return el('div',{class:'form'},inp,go);
  }
  function chip(){
    return el('button',{type:'button',class:'chip',onclick:()=>setView('settings')},
      '专注 '+S.settings.focusMin+' 分 · 休息 '+S.settings.breakMin+' 分 · 调整');
  }

  function stepper(kind,label,val){
    const lo=1,hi=kind==='focus'?180:60;
    const inp=el('input',{class:'num',type:'number',min:String(lo),max:String(hi),step:'1',value:String(val),'aria-label':label+'时长（分钟）',
      onchange:()=>changeDur(kind,()=>inp.value)});
    return el('div',{class:'step'},
      el('span',{class:'lab'},label),
      el('button',{type:'button',class:'sbtn','aria-label':label+'减1分钟',onclick:()=>changeDur(kind,o=>o-1)},'−'),
      inp,
      el('button',{type:'button',class:'sbtn','aria-label':label+'加1分钟',onclick:()=>changeDur(kind,o=>o+1)},'+'));
  }
  function durBox(withHint){
    const kids=[
      el('div',{class:'dh'},'时长（分钟）'),
      stepper('focus','专注',S.settings.focusMin),
      stepper('break','休息',S.settings.breakMin)
    ];
    if(withHint)kids.push(el('div',{class:'hint'},'进行中的同类阶段会同步增减剩余时间，之后每轮沿用此时长。'));
    return el('div',{class:'dur'},...kids);
  }

  function listBox(){
    const mins=todayRounds.reduce((a,r)=>a+(r.minutes||0),0);
    const n=todayRounds.length;
    const rows=todayRounds.map((r,i)=>({r:r,i:i})).reverse().map(o=>
      el('li',{class:'row'},
        el('span',{class:'no'},'#'+(o.i+1)),
        el('span',{class:'rt'},o.r.task),
        el('span',{class:'rm'},hhmm(o.r.at))));
    const body=n?el('ul',{class:'rows'},...rows):el('div',{class:'empty'},'今天还没有完成的专注轮次');
    return el('div',{class:'lst'},
      el('div',{class:'dh'},'今日已完成 '+n+' 轮'+(n?' · 共 '+mins+' 分钟':'')),
      body);
  }


  function mainParts(){
    const parts=[head()];
    if(size==='3x3'){
      parts.push(!ses
        ?el('div',{class:'body'},form(),chip())
        :el('div',{class:'body'},taskBlock(),bar(),controls()));
    }else if(size==='6x3'){
      const right=!ses?[form(),chip()]:[taskBlock(),controls()];
      parts.push(el('div',{class:'top'},ring(),el('div',{class:'col'},...right)));
    }else if(size==='3x6'){
      const mid=!ses?[form()]:[taskBlock(),controls()];
      parts.push(el('div',{class:'body tall'},ring(),...mid,durBox(false),listBox()));
    }else{
      const right=!ses?[form()]:[taskBlock(),controls()];
      parts.push(el('div',{class:'top'},ring(),el('div',{class:'col'},...right)));
      parts.push(el('div',{class:'bottom'},el('div',{class:'dwrap'},durBox(true)),listBox()));
    }
    return parts;
  }

  function render(){
    let parts;
    if(view==='settings')parts=[subHead('时长设置'),el('div',{class:'body'},durBox(true))];
    else if(view==='rounds')parts=[subHead('今日记录'),el('div',{class:'body'},listBox())];
    else parts=mainParts();
    root.appendChild(el('div',{class:'wrap','data-phase':phaseOf()},...parts));
  }

  render();
  paint();
  t0=setTimeout(tick,0);
  timer=setInterval(tick,ses&&ses.status==='running'?250:20000);
  return ()=>{clearTimeout(t0);clearInterval(timer)};
}

